#ifndef FASTP2P_SECURE_H
#define FASTP2P_SECURE_H
#include <stddef.h>
#include <stdint.h>

/* Tunnel payload protection for fastp2p2.
 *
 * A 256-bit session secret is generated by the initiating client and delivered
 * to the peer over the TLS-authenticated gateway channel, so a relay node that
 * forwards the tunnel frames never learns it.  Both sides expand that secret
 * with HKDF-SHA256 into one AES-256-GCM key per direction, so the two
 * directions never share a nonce space.  Every tunnel frame carries a strictly
 * increasing 64-bit sequence number that is also the nonce, and the receiver
 * rejects duplicates and stale frames with a sliding window. */
#define FP_SESSION_SECRET 32
#define FP_TAG 16
#define FP_AAD 10

typedef struct {
    uint8_t tx[32];
    uint8_t rx[32];
    uint64_t tx_seq;
    uint64_t rx_max;
    uint64_t rx_seen;
    int rx_started;
    int broken;
} fp_crypto;

/* initiator_id and responder_id are the two node identifiers; they bind the
 * derived keys to this pair of peers so a frame cannot be replayed onto a
 * different session that happens to reuse the secret.  Both sides call this
 * with identical arguments; local_initiator selects which direction key is
 * used for transmission. */
int fp_crypto_init(fp_crypto *c, const uint8_t secret[FP_SESSION_SECRET], uint64_t session,
                   uint64_t initiator_id, uint64_t responder_id, int local_initiator);
/* out must provide len + FP_TAG bytes.  aad binds the frame type and the
 * overlay identifier to the ciphertext. */
int fp_seal(fp_crypto *c, uint16_t sub, uint64_t overlay, const void *in, size_t len, uint8_t *out,
            size_t capacity, size_t *written);
int fp_open(fp_crypto *c, uint16_t sub, uint64_t overlay, const void *in, size_t len, uint8_t *out,
            size_t capacity, size_t *written);
void fp_crypto_clear(fp_crypto *c);

/* Relay join authentication: proves domain membership without putting the
 * installation token on the wire. */
void fp_join_proof(const uint64_t token, uint64_t session, uint64_t peer, uint8_t out[16]);
int fp_equal(const void *a, const void *b, size_t len);
/* OS CSPRNG; aborts rather than returning predictable bytes. */
void fp_random(void *out, size_t len);
#endif
